from taf.gnb.oam.ne3s.ws.components.UM.v1.UM import UMv1
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_connection import NE3SConnection
from taf.gnb.oam.ne3s.ws.components.CM import CMv1
from taf.gnb.oam.ne3s.ws.components.SWM import SWMv1
from taf.gnb.oam.ne3s.ws.components.FM import FMv1
from taf.gnb.oam.ne3s.ws.components.PM import PMv1
from taf.gnb.oam.ne3s.ws.components.ATL import ATLv1
from taf.gnb.oam.ne3s.ws.components.CERT import CERTv1

from taf.gnb.oam.ne3s.ws.interfaces.base import NE3SInterface


class v5G19A(NE3SInterface):
    connection = None

    def __init__(self, connection_details):
        """
        :param connection_details taf.gnb.oam.ne3s.ws.provider.NE3SConnectionDetails: path to the SW package in .zip format
        """

        self.connection = NE3SConnection(connection_details=connection_details)
        self.cm = CMv1(connection=self.connection)
        self.swm = SWMv1(connection=self.connection)
        self.fm = FMv1(connection=self.connection)
        self.pm = PMv1(connection=self.connection)
        self.atl = ATLv1(connection=self.connection)
        self.cert = CERTv1(connection=self.connection)
        self.um = UMv1(connection=self.connection)

        combined_streams = (self.cm.STREAMS
                            + self.swm.STREAMS
                            + self.fm.STREAMS
                            + self.atl.STREAMS
                            + self.pm.STREAMS
                            + self.cert.STREAMS
                            + self.um.STREAMS)

        self.filter = self.create_filter(connection_details.name, *combined_streams)
        self.connection.notifications.update_filters(new_filters=[self.filter])
